function toMin(t){ if(!t) return null; const m=/^(\d{1,2}):(\d{2})$/.exec(String(t).trim()); if(!m) return null; return (+m[1])*60 + (+m[2]); }
const rows = $input.all().map(i => i.json);
const onTime=[], late=[], absent=[];
for (const r of rows){
  const name=r.fullName; const exp=r.expectedAt; const arr=r.arrivedAt;
  const txt=(r.entryText||'').toUpperCase();
  if (txt==='FALTA'){ absent.push(name); continue; }
  if (txt && txt!=='CONTEO'){ continue; } // descanso/vacaciones/pago: no se juzga
  if (r.schedStatus && r.schedStatus!=='WORKING'){ continue; } // no le tocaba
  if (!arr){ absent.push(name); continue; }
  const e=toMin(exp), a=toMin(arr);
  if (e===null || a===null){ onTime.push(name); continue; }
  const ml=a-e;
  if (ml<=14) onTime.push(name); else if (ml<30) late.push(name+' (+'+ml+'m)');
  // >=30 = permiso/entrada tarde: no es retardo ni falta
}
const d = new Date().toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Monterrey' });
let text = '📊 *Cierre de hoy — ' + d + '*\n';
text += '✅ ' + onTime.length + ' a tiempo' + (onTime.length? ' ('+onTime.join(', ')+')':'') + '\n';
text += '🕐 ' + late.length + ' retardos' + (late.length? ' ('+late.join(', ')+')':'') + '\n';
text += '❌ ' + absent.length + ' faltas' + (absent.length? ' ('+absent.join(', ')+')':'');
return [{ json: { text } }];

// Una sola alerta al cierre, solo a Adrián. Si se cumplió la meta o no hay meta
// cargada, no se manda nada. Sin captura no se puede saber: se dice, no se supone.
const r = $input.first().json;
if (r.error || !r.dia) {
  return [{ json: { text: '⚠️ *Cierre:* no pude revisar la venta de hoy contra la meta. Revísalo en la app.' } }];
}
const dinero = (n) => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pct = (a, b) => (Number(a) / Number(b) * 100).toFixed(1) + '%';
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const [, m, d] = r.dia.split('-');
const fecha = Number(d) + ' ' + MESES[Number(m) - 1];
const nombre = (n) => (n.includes('ADRIAN') ? 'Adrián' : n.split(' ')[0].charAt(0) + n.split(' ')[0].slice(1).toLowerCase());
const ventas = Number(r.ventas), meta = Number(r.meta);
if (!(meta > 0)) return [];
if (!r.con_captura) {
  return [{ json: { text: 'ℹ️ *Cierre ' + fecha + ':* a las 22:05 no hay venta capturada, así que no sé si se llegó a la meta de ' + dinero(meta) + '.' } }];
}
if (ventas >= meta) return [];
let text = '⚠️ *Cierre ' + fecha + ': NO se llegó a la meta*\n'
  + '💰 Venta: ' + dinero(ventas) + ' de ' + dinero(meta) + ' (' + pct(ventas, meta) + ')\n'
  + '📉 Faltaron: ' + dinero(meta - ventas) + '\n'
  + '🧾 Tickets: ' + r.tickets + ' · Piezas: ' + r.piezas;
if (Number(r.meta_semana) > 0) {
  text += '\n📅 Semana a la fecha: ' + dinero(r.ventas_semana) + ' de ' + dinero(r.meta_semana) + ' (' + pct(r.ventas_semana, r.meta_semana) + ')';
}
const gente = typeof r.por_persona === 'string' ? JSON.parse(r.por_persona) : r.por_persona;
if (gente && gente.length) text += '\n👥 ' + gente.map((p) => nombre(p.nombre) + ' ' + dinero(p.ventas)).join(' · ');
if (r.ultima_captura && r.ultima_captura < r.dia + ' 20:00') {
  text += '\n🕐 Ojo: la captura es de las ' + r.ultima_captura.slice(-5) + ', quizá falta venta por subir.';
}
return [{ json: { text } }];
